1	package com.example.starter.fermentation.repository;
2	
3	import com.example.starter.fermentation.domain.CurvePhase;
4	import com.example.starter.fermentation.domain.CurveSegment;
5	import org.springframework.jdbc.core.JdbcTemplate;
6	import org.springframework.jdbc.core.RowMapper;
7	import org.springframework.stereotype.Repository;
8	
9	import java.math.BigDecimal;
10	import java.util.List;
11	import java.util.Optional;
12	
13	/**
14	 * 工艺曲线数据访问。曲线按版本管理，历史版本只读保留，支持按经过时长复算设定值。
15	 */
16	@Repository
17	public class CurveRepository {
18	
19	    private static final RowMapper<CurveSegment> SEGMENT_MAPPER = (rs, rowNum) -> new CurveSegment(
20	            rs.getLong("id"),
21	            rs.getLong("curve_id"),
22	            CurvePhase.valueOf(rs.getString("phase")),
23	            rs.getInt("seq"),
24	            rs.getBigDecimal("setpoint_celsius"),
25	            rs.getInt("duration_hours"));
26	
27	    private final JdbcTemplate jdbc;
28	
29	    public CurveRepository(JdbcTemplate jdbc) {
30	        this.jdbc = jdbc;
31	    }
32	
33	    /**
34	     * 查询曲线当前生效（ACTIVE）的最新版本号。
35	     */
36	    public Optional<Integer> findActiveVersion(String curveCode) {
37	        return jdbc.query(
38	                "SELECT version FROM process_curve WHERE curve_code = ? AND status = 'ACTIVE'"
39	                        + " ORDER BY version DESC LIMIT 1",
40	                rs -> rs.next() ? Optional.of(rs.getInt(1)) : Optional.empty(), curveCode);
41	    }
42	
43	    /**
44	     * 查询指定版本的分段（按阶段过滤、序号升序）。
45	     */
46	    public List<CurveSegment> findSegments(String curveCode, int version, CurvePhase phase) {
47	        return jdbc.query(
48	                "SELECT s.* FROM curve_segment s JOIN process_curve c ON s.curve_id = c.id"
49	                        + " WHERE c.curve_code = ? AND c.version = ? AND s.phase = ? ORDER BY s.seq",
50	                SEGMENT_MAPPER, curveCode, version, phase.name());
51	    }
52	
53	    /**
54	     * 按阶段经过时长（小时）复算设定值：分段按 seq 依次生效，超出末段后沿用末段设定值。
55	     *
56	     * @throws IllegalStateException 曲线缺少该阶段分段
57	     */
58	    public BigDecimal setpointAt(String curveCode, int version, CurvePhase phase, long elapsedHours) {
59	        List<CurveSegment> segments = findSegments(curveCode, version, phase);
60	        if (segments.isEmpty()) {
61	            throw new IllegalStateException(
62	                    "曲线 " + curveCode + " v" + version + " 缺少阶段 " + phase + " 的分段设定");
63	        }
64	        long remaining = elapsedHours;
65	        for (CurveSegment segment : segments) {
66	            if (remaining < segment.durationHours()) {
67	                return segment.setpointCelsius();
68	            }
69	            remaining -= segment.durationHours();
70	        }
71	        return segments.get(segments.size() - 1).setpointCelsius();
72	    }
73	}
